translations.db8d4b588cc8c033ae3a6144de6107d9e7aa0b8a:
Check は、bool を返す任意の関数 f について、
f が false を返す入力を探します。各引数に任意の値を与えて、
f を繰り返し呼び出します。ある入力に対して f が false を返した場合、
Check はその入力を *[CheckError] として返します。
例:

	func TestOddMultipleOfThree(t *testing.T) {
		f := func(x int) bool {
			y := OddMultipleOfThree(x)
			return y%2 == 1 && y%3 == 0
		}
		if err := quick.Check(f, nil); err != nil {
			t.Error(err)
		}
	}

